const originals=new WeakMap();
function T(value){const language=window.MQI18n?.language;if(!language||language==='zh-CN')return value;const i=language==='es'?1:0,s=String(value);if(words[s])return words[s][i];let out=s
 .replace(/^已晋级 (\d+) \/ 4 轮$/,(_,n)=>i?`Avanzaste ${n} / 4 rondas`:`Advanced ${n} / 4 rounds`)
 .replace(/^开局最多约 (\d+) 秒 · 复杂局面最多约 (\d+) 秒$/,(_,a,b)=>i?`Apertura: hasta ${a} s · Posiciones complejas: hasta ${b} s`:`Opening: up to ${a}s · Complex positions: up to ${b}s`)
 .replace(/^(\d+) 人 · /,(_,n)=>i?`${n} jugadores · `:`${n} players · `)
 .replace(/^第 (\d+) 场$/,(_,n)=>i?`PARTIDA ${n}`:`MATCH ${n}`)
 .replace(/^(.+)，本届冠军。$/,(_,n)=>i?`${n}, campeón del torneo.`:`${n}, this tournament's champion.`)
 .replace(/^你取得 (\d+) 场胜利。下一次相逢，再向冠军发起挑战。$/,(_,n)=>i?`Ganaste ${n} partidas. Vuelve a luchar por el título.`:`You won ${n} matches. Come back and challenge for the title.`)
 .replace(/ · 和棋 (\d+) 次，本轮重赛$/,(_,n)=>i?` · ${n} tablas; se repite la ronda`:` · ${n} draws; replay this round`)
 .replace(/^恭喜晋级(.+)！下一位对手已就位。$/,(_,r)=>i?`¡Avanzas a ${T(r)}! Tu próximo rival te espera.`:`You advance to ${T(r)}! Your next opponent is ready.`)
 .replace(/^本次大师赛止步于(.+)，下次再战。$/,(_,r)=>i?`Tu torneo termina en ${T(r)}. ¡Hasta la próxima!`:`Your tournament ends in the ${T(r)}. See you next time.`);
 for(const k of Object.keys(words).sort((a,b)=>b.length-a.length))out=out.split(k).join(words[k][i]);return out;}
function localize(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){const prev=originals.get(n),s=prev&&prev.rendered===n.nodeValue?prev.source:n.nodeValue,trim=s.trim(),rendered=trim?s.replace(trim,T(trim)):s;originals.set(n,{source:s,rendered});if(n.nodeValue!==rendered)n.nodeValue=rendered;}}

