const entry=document.createElement('button');entry.type='button';entry.id='openMasters';entry.setAttribute('data-no-i18n','');entry.className='masters-entry';entry.innerHTML='<span class="masters-entry-cup">'+cup+'</span><span><strong>象力大师赛</strong><small>战胜宗师或提交反馈解锁</small></span><span class="masters-entry-state">'+lock+'</span>';
